/* ADJUDICATION PROBE, not a test and not part of the crate.
 *
 * Reproduces the D-LEGACY-MD-INIT-MD-DATA-1 shape for the three legacy
 * initialisers the 46-file triage found unfixed (MD4, RIPEMD-160, Whirlpool):
 *
 *   init = EVP_MD_meth_get_init(EVP_md4());   // exported getter
 *   ctx  = EVP_MD_CTX_new();                  // zero-filled: md_data == NULL
 *   init(ctx);                                // authority writes through NULL
 *
 * One digest per process (argv[1]), so a SIGSEGV is an observed result.
 * Compiled and run against one install prefix per invocation.
 */
#include <stdio.h>
#include <string.h>
#include <openssl/evp.h>

typedef int (*init_fn)(EVP_MD_CTX *);

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "usage: %s {md4|ripemd160|whirlpool|md5|sha1}\n", argv[0]);
        return 2;
    }
    const EVP_MD *md = NULL;
    if (strcmp(argv[1], "md4") == 0) md = EVP_md4();
    else if (strcmp(argv[1], "ripemd160") == 0) md = EVP_ripemd160();
    else if (strcmp(argv[1], "whirlpool") == 0) md = EVP_whirlpool();
    else if (strcmp(argv[1], "md5") == 0) md = EVP_md5();
    else if (strcmp(argv[1], "sha1") == 0) md = EVP_sha1();
    else { fprintf(stderr, "unknown digest\n"); return 2; }

    if (md == NULL) { printf("%s: method=NULL\n", argv[1]); return 3; }
    init_fn init = (init_fn)EVP_MD_meth_get_init(md);
    EVP_MD_CTX *ctx = EVP_MD_CTX_new();
    if (init == NULL || ctx == NULL) {
        printf("%s: init=%p ctx=%p (no crash)\n", argv[1], (void *)init, (void *)ctx);
        return 3;
    }
    fflush(stdout);
    /* The authority's documented fault: no test on the context's md_data. */
    int r = init(ctx);
    printf("%s: init(ctx) returned %d (no crash)\n", argv[1], r);
    EVP_MD_CTX_free(ctx);
    return 0;
}
